from collections import deque

def bfs(adj, start):
    visited = {start}
    order = []
    # deque, not a list: list.pop(0) has to shift every remaining
    # element along, which quietly turns this into O(V^2).
    queue = deque([start])

    while queue:
        node = queue.popleft()      # <- take from the FRONT
        order.append(node)

        for nxt in adj.get(node, []):
            if nxt in visited:
                continue
            visited.add(nxt)        # mark on the way IN, not on the way out
            queue.append(nxt)

    return order

