def dfs_recursive(adj, node, visited=None, order=None):
    # Do not write visited=set() in the signature. Python builds that
    # default once, at definition time, so every later call would share
    # the same set and the second traversal would find everything
    # already visited.
    if visited is None:
        visited = set()
    if order is None:
        order = []

    if node in visited:
        return order
    visited.add(node)
    order.append(node)

    for nxt in adj.get(node, []):
        dfs_recursive(adj, nxt, visited, order)

    return order

