std::vector<std::string> pathTo(
    const std::map<std::string, std::string>& parent,
    const std::string& target) {
    std::vector<std::string> path{target};
    while (parent.count(path.front())) {
        path.insert(path.begin(), parent.at(path.front()));
    }
    return path;
